CREATE OR REPLACE FUNCTION public.tms_import_cte_worker(xml_text text,actor uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_claims text; result jsonb; BEGIN IF coalesce(auth.role(),'')<>'service_role' OR NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.id WHERE p.id=actor AND p.ativo AND ur.role='admin') THEN RAISE EXCEPTION 'Responsável ativo autorizado necessário'; END IF; old_claims:=current_setting('request.jwt.claims',true); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true); result:=public.tms_import_cte(xml_text); PERFORM set_config('request.jwt.claims',old_claims,true); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.tms_import_cte_worker(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.tms_import_cte_worker(text,uuid) TO service_role;
REVOKE EXECUTE ON FUNCTION public.tms_access_selftest(), public.tms_extended_selftest() FROM authenticated;